<?php
declare(strict_types=1);session_start();
spl_autoload_register(function(string $class):void{$prefix='MyGame\\';if(!str_starts_with($class,$prefix))return;$p=__DIR__.'/../src/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($p))require$p;});
use MyGame\Infrastructure\Database\Connection;use MyGame\Infrastructure\Market\BusinessOperationsRepository;
$db=Connection::make();(new \MyGame\Infrastructure\Economy\GameEconomyEngine($db))->sync();$companyId=(int)($_SESSION['company_id']??1);$repo=new BusinessOperationsRepository($db);$error=null;$notice=null;$_SESSION['ops_csrf']??=bin2hex(random_bytes(24));$csrf=$_SESSION['ops_csrf'];
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Neteisinga užklausa.');$a=(string)($_POST['action']??'');if($a==='rent'){$repo->rentProperty($companyId,(int)$_POST['id']);$notice='Patalpos išnuomotos.';}elseif($a==='hire'){$repo->hire($companyId,(int)$_POST['role_id'],(float)str_replace(',','.',$_POST['salary']));$notice='Darbuotojas priimtas.';}elseif($a==='dismiss'){$repo->dismiss($companyId,(int)$_POST['id']);$notice='Darbuotojas atleistas.';}elseif($a==='order'){$repo->order($companyId,(int)$_POST['supplier_id'],(int)$_POST['product_id'],(float)$_POST['qty']);$notice='Užsakymas pateiktas.';}elseif($a==='price'){$repo->setPrice($companyId,(int)$_POST['product_id'],(float)str_replace(',','.',$_POST['price']));$notice='Kaina pakeista.';}elseif($a==='marketing'){$repo->marketing($companyId,(float)str_replace(',','.',$_POST['budget']));$notice='Marketingo biudžetas atnaujintas.';}}
$data=['properties'=>$repo->properties($companyId),'roles'=>$repo->roles(),'employees'=>$repo->employees($companyId),'products'=>$repo->products($companyId),'suppliers'=>$repo->suppliers($companyId),'marketing'=>$repo->marketingData($companyId),'orders'=>$repo->orders($companyId)];}catch(Throwable$e){$error=$e->getMessage();$data=['properties'=>[],'roles'=>[],'employees'=>[],'products'=>[],'suppliers'=>[],'marketing'=>[],'orders'=>[]];}
require __DIR__.'/../src/Presentation/operations.php';
